// TypeScript Model: NGFS Climate Scenario Risk Multiplier Engine
interface NgfsScenarioParameters {
  scenarioName: 'ORDERLY_1_5C' | 'DISORDERLY_2_0C' | 'HOT_HOUSE_WORLD_3_PLUS';
  carbonTaxDollarsPerTon: number;
  renewableEnergySharePercent: number;
  globalTemperatureIncreaseCelsius: number;
  transitionRiskMultiplier: number;
  physicalRiskMultiplier: number;
}

interface CorporateBorrowerProfile {
  borrowerId: string;
  industrySector: 'COAL_POWER' | 'RENEWABLE_SOLAR' | 'CEMENT_STEEL' | 'COASTAL_LOGISTICS';
  loanOutstandingCrores: number;
  baselinePDPercent: number; // Baseline Probability of Default
}

function calculateClimateAdjustedPd(
  borrower: CorporateBorrowerProfile,
  scenario: NgfsScenarioParameters
): {
  adjustedPDPercent: number;
  expectedLossImpactCrores: number;
  riskCategory: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
} {
  let riskWeight = 1.0;

  if (borrower.industrySector === 'COAL_POWER') {
    // Extreme sensitivity to carbon taxes and transition policy
    riskWeight = 1.0 + (scenario.carbonTaxDollarsPerTon / 50.0) * scenario.transitionRiskMultiplier;
  } else if (borrower.industrySector === 'CEMENT_STEEL') {
    // High emission intensity with moderate transition abatement costs
    riskWeight = 1.0 + (scenario.carbonTaxDollarsPerTon / 100.0) * scenario.transitionRiskMultiplier * 0.7;
  } else if (borrower.industrySector === 'COASTAL_LOGISTICS') {
    // Severe physical risk from sea level rise and typhoons
    riskWeight = 1.0 + (scenario.globalTemperatureIncreaseCelsius / 1.5) * scenario.physicalRiskMultiplier;
  } else if (borrower.industrySector === 'RENEWABLE_SOLAR') {
    // Green beneficiary; transition reduces default risk
    riskWeight = Math.max(0.4, 1.0 - (scenario.renewableEnergySharePercent / 150.0));
  }

  const adjustedPD = Math.min(100.0, borrower.baselinePDPercent * riskWeight);
  const lgd = 0.45; // Standard 45% Loss Given Default
  const expectedLoss = (borrower.loanOutstandingCrores * (adjustedPD / 100.0)) * lgd;

  let category: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' = 'LOW';
  if (adjustedPD >= 20.0) category = 'CRITICAL';
  else if (adjustedPD >= 10.0) category = 'HIGH';
  else if (adjustedPD >= 5.0) category = 'MEDIUM';

  return {
    adjustedPDPercent: Math.round(adjustedPD * 100) / 100,
    expectedLossImpactCrores: Math.round(expectedLoss * 100) / 100,
    riskCategory: category
  };
}

// TypeScript Model: Carbon Tax Transition Stress Testing & EBITDA Degradation Engine
interface CorporateTransitionProfile {
  companyName: string;
  currentEbitdaCrores: number;
  annualDebtServiceCrores: number;
  annualScope1EmissionsTons: number;
  annualScope2EmissionsTons: number;
  costPassThroughAbilityPercent: number; // Ability to pass carbon cost to buyers
}

function evaluateCarbonTaxTransitionStress(
  company: CorporateTransitionProfile,
  carbonTaxDollarsPerTon: number,
  fxRateInrPerDollar: number
) {
  console.log(`=== CARBON TAX TRANSITION STRESS TEST: ${company.companyName} ===`);

  const totalEmissionsTons = company.annualScope1EmissionsTons + company.annualScope2EmissionsTons;
  const totalCarbonCostDollars = totalEmissionsTons * carbonTaxDollarsPerTon;
  const totalCarbonCostCrores = (totalCarbonCostDollars * fxRateInrPerDollar) / 1e7;

  // Net carbon cost absorbed by company after pass-through to customers
  const netCarbonCostAbsorbedCrores = totalCarbonCostCrores * (1.0 - (company.costPassThroughAbilityPercent / 100.0));
  const stressedEbitdaCrores = company.currentEbitdaCrores - netCarbonCostAbsorbedCrores;

  const baselineDscr = company.currentEbitdaCrores / company.annualDebtServiceCrores;
  const stressedDscr = stressedEbitdaCrores / company.annualDebtServiceCrores;

  console.log(`Annual Carbon Emissions: ${(totalEmissionsTons / 1000).toFixed(1)}k Tons CO2e`);
  console.log(`Simulated Carbon Tax: $${carbonTaxDollarsPerTon}/ton (₹${(carbonTaxDollarsPerTon * fxRateInrPerDollar).toFixed(0)}/ton)`);
  console.log(`Gross Carbon Liability: ₹${totalCarbonCostCrores.toFixed(2)} Cr | Pass-Through: ${company.costPassThroughAbilityPercent}%`);
  console.log(`Net Cost Absorbed: ₹${netCarbonCostAbsorbedCrores.toFixed(2)} Cr`);
  console.log(`Baseline EBITDA: ₹${company.currentEbitdaCrores.toFixed(2)} Cr -> Stressed EBITDA: ₹${stressedEbitdaCrores.toFixed(2)} Cr`);
  console.log(`Baseline DSCR: ${baselineDscr.toFixed(2)}x -> Stressed DSCR: ${stressedDscr.toFixed(2)}x`);

  const isDefaultRisk = stressedDscr < 1.0;
  console.log(`Credit Solvency Status: ${isDefaultRisk ? '🚨 DEFAULT IMMINENT (DSCR < 1.0x)' : 'STABLE BUFFER'}`);

  return {
    stressedEbitdaCrores,
    stressedDscr,
    isDefaultRisk
  };
}

// TypeScript Model: PCAF Financed Emissions & Carbon Intensity Calculator
interface PcafCorporateAsset {
  borrowerName: string;
  loanExposureCrores: number;
  evicOrTotalCapitalCrores: number;
  annualRevenueCrores: number;
  scope1EmissionsTonsCo2: number;
  scope2EmissionsTonsCo2: number;
  pcafDataQualityScore: 1 | 2 | 3 | 4 | 5;
}

function calculatePcafFinancedEmissions(portfolio: PcafCorporateAsset[]) {
  console.log('=== PCAF SCOPE 3 CATEGORY 15 FINANCED EMISSIONS AUDIT ===');

  let totalPortfolioExposure = 0;
  let totalFinancedEmissions = 0;
  let weightedCarbonIntensitySum = 0;
  let weightedDataQualitySum = 0;

  portfolio.forEach(asset => {
    totalPortfolioExposure += asset.loanExposureCrores;

    // 1. Calculate PCAF Attribution Factor
    const attributionFactor = asset.loanExposureCrores / asset.evicOrTotalCapitalCrores;

    // 2. Absolute Financed Emissions
    const clientTotalEmissions = asset.scope1EmissionsTonsCo2 + asset.scope2EmissionsTonsCo2;
    const financedEmissions = attributionFactor * clientTotalEmissions;
    totalFinancedEmissions += financedEmissions;

    // 3. Client Carbon Intensity (Tons CO2e per ₹ Cr Revenue)
    const carbonIntensity = clientTotalEmissions / asset.annualRevenueCrores;

    console.log(`Borrower: ${asset.borrowerName}`);
    console.log(`- Loan Exposure: ₹${asset.loanExposureCrores} Cr | EVIC: ₹${asset.evicOrTotalCapitalCrores} Cr`);
    console.log(`- PCAF Attribution Factor: ${(attributionFactor * 100).toFixed(2)}%`);
    console.log(`- Client Emissions: ${(clientTotalEmissions / 1000).toFixed(1)}k Tons CO2e | Bank Financed: ${(financedEmissions / 1000).toFixed(1)}k Tons CO2e`);
    console.log(`- Carbon Intensity: ${carbonIntensity.toFixed(1)} tCO2e/₹Cr | Data Quality: ${asset.pcafDataQualityScore}`);

    weightedDataQualitySum += asset.pcafDataQualityScore * asset.loanExposureCrores;
  });

  const portfolioDataQualityScore = weightedDataQualitySum / totalPortfolioExposure;
  const portfolioCarbonIntensity = totalFinancedEmissions / totalPortfolioExposure;

  console.log('---------------------------------------------------------');
  console.log(`Total Portfolio Exposure: ₹${totalPortfolioExposure.toFixed(2)} Cr`);
  console.log(`Total Financed Emissions: ${(totalFinancedEmissions / 1000).toFixed(2)}k Tons CO2e`);
  console.log(`Portfolio Carbon Intensity: ${portfolioCarbonIntensity.toFixed(2)} Tons CO2e / ₹Cr Loan`);
  console.log(`Weighted PCAF Data Quality Score: ${portfolioDataQualityScore.toFixed(2)} / 5.0 (Target: <= 2.0)`);
  console.log('=========================================================');

  return {
    totalPortfolioExposure,
    totalFinancedEmissions,
    portfolioDataQualityScore
  };
}

// TypeScript Model: ICMA Green Bond Framework & Proceed Allocation Engine
interface GreenBondProject {
  projectId: string;
  name: string;
  category: 'RENEWABLE_ENERGY' | 'CLEAN_TRANSPORT' | 'ENERGY_EFFICIENCY' | 'FOSSIL_COGENERATION';
  requestedAmountCrores: number;
  annualAvoidedCo2Tons: number;
  meetsDnshCriteria: boolean; // Do No Significant Harm
  meetsSocialSafeguards: boolean;
}

interface GreenBondIssuance {
  bondTicker: string;
  totalProceedsCrores: number;
  couponRatePercent: number;
  greeniumBps: number;
  eligibleProjects: GreenBondProject[];
}

function auditGreenBondIssuance(issuance: GreenBondIssuance) {
  console.log(`=== ICMA GREEN BOND COMPLIANCE AUDIT: ${issuance.bondTicker} ===`);
  console.log(`Total Issuance Proceeds: ₹${issuance.totalProceedsCrores.toFixed(2)} Cr`);
  console.log(`Priced Coupon: ${issuance.couponRatePercent.toFixed(2)}% (Greenium Benefit: ${issuance.greeniumBps} bps)`);
  console.log('---------------------------------------------------------');

  let allocatedCapitalCrores = 0;
  let totalAvoidedCo2Tons = 0;
  const rejectedProjects: string[] = [];

  issuance.eligibleProjects.forEach(proj => {
    // Taxonomy Validation: Fossil projects disqualified; DNSH and Social Safeguards mandatory
    const isCategoryEligible = proj.category !== 'FOSSIL_COGENERATION';
    const isTaxonomyAligned = isCategoryEligible && proj.meetsDnshCriteria && proj.meetsSocialSafeguards;

    if (isTaxonomyAligned) {
      allocatedCapitalCrores += proj.requestedAmountCrores;
      totalAvoidedCo2Tons += proj.annualAvoidedCo2Tons;
      console.log(`✅ ALLOCATED: [${proj.category}] ${proj.name} -> ₹${proj.requestedAmountCrores} Cr (Avoids ${proj.annualAvoidedCo2Tons.toLocaleString()} tCO2/yr)`);
    } else {
      rejectedProjects.push(proj.name);
      console.log(`❌ DISQUALIFIED: ${proj.name} (Breaches Taxonomy / DNSH / Social Safeguards)`);
    }
  });

  const unallocatedProceeds = issuance.totalProceedsCrores - allocatedCapitalCrores;
  console.log('---------------------------------------------------------');
  console.log(`Total Allocated Proceeds: ₹${allocatedCapitalCrores.toFixed(2)} Cr`);
  console.log(`Unallocated Proceeds (Held in Liquid G-Secs): ₹${unallocatedProceeds.toFixed(2)} Cr`);
  console.log(`Total Environmental Impact: ${totalAvoidedCo2Tons.toLocaleString()} Metric Tons CO2e Avoided/Year`);
  console.log(`Green Bond Principle Compliance Status: ${unallocatedProceeds >= 0 ? 'CERTIFIED PASS (Pillars 1-4 Satisfied)' : 'OVERALLOCATION_ERROR'}`);
  console.log('=========================================================');

  return {
    allocatedCapitalCrores,
    unallocatedProceeds,
    totalAvoidedCo2Tons,
    isCertified: unallocatedProceeds >= 0
  };
}

// Industrial TypeScript Simulation: Bank Climate Risk & ESG Solvency War Room
interface PortfolioLoanAsset {
  obligor: string;
  sector: string;
  loanExposureCrores: number;
  evicCrores: number;
  annualScope1And2Co2Tons: number;
  baselineEbitdaCrores: number;
  annualDebtServiceCrores: number;
  isCollateralCoastal: boolean;
}

function runClimateRiskSolvencyWarRoom() {
  console.log('=== INDUSTRIAL CLIMATE RISK & ESG SOLVENCY WAR ROOM ===');
  console.log('Supervisory Scenario: NGFS Disorderly Transition + IPCC RCP 8.5 Severe Shock');
  console.log('Portfolio Size: ₹10,000.00 Cr Corporate Wholesale Lending');
  console.log('--------------------------------------------------------\n');

  const portfolio: PortfolioLoanAsset[] = [
    {
      obligor: 'Mahanadi Thermal Energy Ltd',
      sector: 'Thermal Power',
      loanExposureCrores: 2500,
      evicCrores: 8000,
      annualScope1And2Co2Tons: 6500000,
      baselineEbitdaCrores: 620,
      annualDebtServiceCrores: 340,
      isCollateralCoastal: false
    },
    {
      obligor: 'Kalinga Steel & Infrastructure',
      sector: 'Steel Manufacturing',
      loanExposureCrores: 3000,
      evicCrores: 12000,
      annualScope1And2Co2Tons: 4200000,
      baselineEbitdaCrores: 850,
      annualDebtServiceCrores: 410,
      isCollateralCoastal: true
    },
    {
      obligor: 'GreenHorizon Solar & Wind Parks',
      sector: 'Renewable Energy',
      loanExposureCrores: 2500,
      evicCrores: 6000,
      annualScope1And2Co2Tons: 15000,
      baselineEbitdaCrores: 480,
      annualDebtServiceCrores: 220,
      isCollateralCoastal: false
    },
    {
      obligor: 'Metropolis Commercial Towers',
      sector: 'Real Estate & Logistics',
      loanExposureCrores: 2000,
      evicCrores: 5000,
      annualScope1And2Co2Tons: 85000,
      baselineEbitdaCrores: 310,
      annualDebtServiceCrores: 160,
      isCollateralCoastal: true
    }
  ];

  // PHASE 1: PCAF SCOPE 3 FINANCED EMISSIONS AUDIT
  console.log('--- PHASE 1: PCAF FINANCED EMISSIONS AUDIT ---');
  let totalPortfolioExposure = 0;
  let totalFinancedEmissions = 0;

  portfolio.forEach(loan => {
    totalPortfolioExposure += loan.loanExposureCrores;
    const attributionFactor = loan.loanExposureCrores / loan.evicCrores;
    const financedEmissions = attributionFactor * loan.annualScope1And2Co2Tons;
    totalFinancedEmissions += financedEmissions;

    console.log(`Obligor: ${loan.obligor} [${loan.sector}]`);
    console.log(`  Exposure: ₹${loan.loanExposureCrores} Cr | AF: ${(attributionFactor * 100).toFixed(1)}% | Financed CO2e: ${(financedEmissions / 1000).toFixed(0)}k Tons`);
  });

  const baselineWaci = totalFinancedEmissions / totalPortfolioExposure;
  console.log(`Total Portfolio Financed Emissions: ${(totalFinancedEmissions / 1e6).toFixed(2)} Million Tons CO2e`);
  console.log(`Baseline Portfolio Carbon Intensity: ${baselineWaci.toFixed(1)} tCO2e / ₹Cr Loan\n`);

  // PHASE 2: TRANSITION RISK STRESS TEST (CARBON TAX SHOCK: $120/ton = ₹10,080/ton)
  console.log('--- PHASE 2: NGFS TRANSITION STRESS TEST (CARBON TAX $120/TON) ---');
  const carbonPriceInrPerTon = 120 * 84; // $120 * 84 INR
  let totalEclSurgeCrores = 0;

  portfolio.forEach(loan => {
    const grossCarbonCostCrores = (loan.annualScope1And2Co2Tons * carbonPriceInrPerTon) / 1e7;
    // Assume 30% pass-through ability for industrial sectors, 0% for thermal power
    const passThrough = loan.sector === 'Renewable Energy' ? 1.0 : (loan.sector === 'Thermal Power' ? 0.05 : 0.35);
    const netCarbonCostCrores = grossCarbonCostCrores * (1.0 - passThrough);
    const stressedEbitda = loan.baselineEbitdaCrores - netCarbonCostCrores;
    const stressedDscr = stressedEbitda / loan.annualDebtServiceCrores;

    console.log(`Obligor: ${loan.obligor}`);
    console.log(`  Baseline DSCR: ${(loan.baselineEbitdaCrores / loan.annualDebtServiceCrores).toFixed(2)}x -> Stressed DSCR: ${stressedDscr.toFixed(2)}x`);

    if (stressedDscr < 1.0) {
      const eclStage3 = loan.loanExposureCrores * 0.40; // 40% ECL on default
      totalEclSurgeCrores += eclStage3;
      console.log(`  🚨 DEFAULT RATING: Stage 3 Impairment! ECL Provision: ₹${eclStage3.toFixed(2)} Cr`);
    } else if (stressedDscr < 1.30) {
      const eclStage2 = loan.loanExposureCrores * 0.12;
      totalEclSurgeCrores += eclStage2;
      console.log(`  ⚠️ SIGNIFICANT RISK SURGE: Stage 2 Under-Watch! ECL Provision: ₹${eclStage2.toFixed(2)} Cr`);
    } else {
      console.log(`  ✅ RESILIENT: Retains Investment Grade Solvency.`);
    }
  });
  console.log(`Total Climate Transition Credit Impairment (ECL Surge): ₹${totalEclSurgeCrores.toFixed(2)} Cr\n`);

  // PHASE 3: SUSTAINABLE DECARBONIZATION & GREEN BOND MITIGATION
  console.log('--- PHASE 3: GREEN BOND STRUCTURING & BALANCE SHEET REBALANCING ---');
  const greenBondIssueCrores = 2000;
  const greeniumSavingsBps = 15; // 15 bps lower funding cost
  const annualInterestSavingsCrores = (greenBondIssueCrores * (greeniumSavingsBps / 10000));

  console.log(`Green Bond Issued: ₹${greenBondIssueCrores.toFixed(2)} Cr (ICMA Principles Certified)`);
  console.log(`Greenium Pricing Concession: ${greeniumSavingsBps} bps | Annual Net Interest Saved: ₹${annualInterestSavingsCrores.toFixed(2)} Cr`);
  console.log('Capital Rotation: Decarbonizing loan portfolio through dedicated solar/wind deployment.');
  console.log('Regulatory Supervisory Assessment: PASS — Tier 1 Capital Defended & ESG Taxonomy Compliant.');
  console.log('========================================================');
}

runClimateRiskSolvencyWarRoom();
